examples:
const done = after(2, () => "all done");
done(); // undefined — 1st call
done(); // "all done" — 2nd call

type UserId = Brand<string, "UserId">;
type OrderId = Brand<string, "OrderId">;
// a UserId and an OrderId are no longer interchangeable, even though both are strings

type Config = { readonly server: { readonly host: string } };
type EditableConfig = DeepMutable<Config>;
// { server: { host: string } }

type Config = { server: { host: string; port: number } };
type PartialConfig = DeepPartial<Config>;
// { server?: { host?: string; port?: number } }

type Config = { server: { host: string } };
type ImmutableConfig = DeepReadonly<Config>;
// { readonly server: { readonly host: string } }

type Config = { server?: { host?: string; port?: number } };
type FullConfig = DeepRequired<Config>;
// { server: { host: string; port: number } }

type Shape = { kind: "circle"; r: number } | { kind: "square"; s: number };
type WithoutKind = DistributiveOmit<Shape, "kind">;
// { r: number } | { s: number }

const emitter = new EventEmitter();
emitter.on("greet", (name: string) => console.log(`Hello, ${name}!`));
emitter.emit("greet", "world");

const list = new LinkedList<number>();
list.push(1);
list.push(2);
list.toArray(); // [1, 2]

const cache = new LRUCache<string, number>(2);
cache.set("a", 1);
cache.set("b", 2);
cache.set("c", 3); // evicts "a", the least recently used
cache.has("a"); // false

type Base = { id: string; name: string };
type Override = { name: number };
type Merged = Merge<Base, Override>;
// { id: string; name: number }

type Config = { readonly host: string; readonly port: number };
type EditableConfig = Mutable<Config>;
// { host: string; port: number }

interface User { id: string; name: string; email: string }
type NewUser = PartialBy<User, "id">;
// { id?: string; name: string; email: string }

const pq = new PriorityQueue<string>();
pq.push("low", 5);
pq.push("high", 1);
pq.pop(); // "high"

const q = new Queue<number>();
q.enqueue(1);
q.enqueue(2);
q.dequeue(); // 1

interface Filters { id?: string; email?: string; phone?: string }
type Search = RequireAtLeastOne<Filters, "id" | "email" | "phone">;
// needs at least one of id / email / phone

interface Options { id?: string; label?: string }
type WithId = RequiredBy<Options, "id">;
// { id: string; label?: string }

const s = new Stack<number>();
s.push(1);
s.push(2);
s.pop(); // 2

const light = new StateMachine("red", { red: { go: "green" }, green: { stop: "red" } });
light.send("go");
light.state; // "green"

const trie = new Trie();
trie.insert("cat");
trie.has("cat"); // true
trie.startsWith("ca"); // true

type ById = { id: string };
type ByName = { name: string };
type Lookup = XOR<ById, ByName>;
// { id: string } | { name: string } — never both at once
